-- Item stats/required levels: ForeverDB Forever client build 1.60.1.70450 where available.
-- CAUTION: client recipe existence is NOT proof that a vendor/trainer sells its plans.
-- BoP recipes: only the character with that profession can personally craft.
-- Dungeon observation samples are small and NEVER imply a reliable drop rate.

local function New(item)
    assert(not GetGear.ItemCatalog[item.itemID], 'Expanded item collision '..item.itemID)
    assert(GetGear:RegisterItem(item), 'Failed new item '..item.itemID)
end

